      {f"<div class='trade-notice'>{escape(result_message)}<a href='/trade-log'>关闭</a></div>" if result_message else f"<div class='trade-notice error'>{escape(error_message)}<a href='/trade-log'>关闭</a></div>" if error_message else ""}
